import * as React from 'react';
import { cn } from '@/lib/utils';

export type ArticleCardProps = Omit<React.HTMLAttributes<HTMLElement>, 'title'> & {
  /** Article title. */
  title: string;
  /** Summary copy. */
  description?: string;
  /** Destination URL. */
  href: string;
  /** Category or content type. */
  eyebrow?: string;
  /** Image, illustration or video poster. */
  media?: React.ReactNode;
  /** Date, read time, author or other metadata. */
  meta?: React.ReactNode;
  /** Custom link element for routers. */
  linkComponent?: React.ElementType;
  /** Standard card or a denser compact card. */
  variant?: 'default' | 'compact';
};

/**
 * Article or resource card for a content hub. The whole card is one link, so
 * do not nest buttons or other links inside it. Media is a slot so consumers
 * can use next/image, a plain img, a video poster or an illustration.
 */
export const ArticleCard = React.forwardRef<HTMLElement, ArticleCardProps>(function ArticleCard(
  {
    title,
    description,
    href,
    eyebrow,
    media,
    meta,
    linkComponent,
    variant = 'default',
    className,
    ...props
  },
  ref
) {
  const Link = linkComponent ?? 'a';
  const compact = variant === 'compact';

  return (
    <article ref={ref as never} className={cn('h-full', className)} {...props}>
      <Link
        href={href}
        className={cn(
          'group flex h-full flex-col overflow-hidden rounded-xl border border-border bg-card shadow-sm transition-colors hover:border-primary/40',
          'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background'
        )}
      >
        {media && !compact && (
          <div className="aspect-[16/10] w-full overflow-hidden bg-muted [&_img]:h-full [&_img]:w-full [&_img]:object-cover">
            {media}
          </div>
        )}
        <div className={cn('flex flex-1 flex-col gap-2', compact ? 'p-4' : 'p-5')}>
          {eyebrow && (
            <p className="text-xs font-semibold uppercase tracking-widest text-primary">{eyebrow}</p>
          )}
          <h3 className={cn('font-semibold tracking-tight transition-colors group-hover:text-primary', compact ? 'text-base' : 'text-lg')}>
            {title}
          </h3>
          {description && (
            <p className="line-clamp-3 text-sm leading-relaxed text-muted-foreground">{description}</p>
          )}
          {meta && <div className="mt-auto pt-2 text-xs text-muted-foreground">{meta}</div>}
        </div>
      </Link>
    </article>
  );
});

{
  "id": "article-card",
  "name": "ArticleCard",
  "tier": "molecule",
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.5.0",
  "sourceDir": "article-card",
  "exportName": "ArticleCard",
  "description": "Linked article or resource card with media, eyebrow, title, summary and metadata.",
  "designIntent": "Content hubs repeat the same article tile. ArticleCard owns the image aspect, title hierarchy, excerpt clamp and metadata row so blog, resource and LOI pages do not each invent a card.",
  "props": [
    {
      "name": "title",
      "type": "string",
      "required": true,
      "description": "Article title."
    },
    {
      "name": "description",
      "type": "string",
      "required": false,
      "description": "Summary copy."
    },
    {
      "name": "href",
      "type": "string",
      "required": true,
      "description": "Destination URL."
    },
    {
      "name": "eyebrow",
      "type": "string",
      "required": false,
      "description": "Category or content type."
    },
    {
      "name": "media",
      "type": "ReactNode",
      "required": false,
      "description": "Image, illustration or video poster."
    },
    {
      "name": "meta",
      "type": "ReactNode",
      "required": false,
      "description": "Date, read time, author or other metadata."
    },
    {
      "name": "linkComponent",
      "type": "React.ElementType",
      "required": false,
      "description": "Custom link element for routers."
    },
    {
      "name": "variant",
      "type": "'default' | 'compact'",
      "required": false,
      "defaultValue": "default",
      "enum": [
        "default",
        "compact"
      ],
      "description": "Standard card or a denser compact card."
    }
  ],
  "examples": [
    {
      "title": "Resource card",
      "code": "<ArticleCard\n  href=\"/articles/exit-planning\"\n  eyebrow=\"Advisors\"\n  title=\"The 2026 exit planning guide\"\n  description=\"What buyers are looking for.\"\n  meta=\"8 min read\"\n  media={<img src=\"/cover.jpg\" alt=\"\" />}\n/>",
      "description": "A linked article tile for a resource grid."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't nest controls in the card",
      "explanation": "The whole card is one link. Put save, share or menu actions outside the card or redesign the card as a non-link panel.",
      "example": "// Avoid\n<ArticleCard href=\"/x\" title=\"X\" />"
    }
  ],
  "accessibility": [
    {
      "feature": "Single link",
      "implementation": "The card is one link containing the title, summary and metadata",
      "userRequirements": "Use a descriptive title so the link name is meaningful"
    },
    {
      "feature": "Decorative media",
      "implementation": "Media is a slot",
      "userRequirements": "Use alt=\"\" for decorative covers or a meaningful alt for informative images"
    }
  ],
  "compositionRules": [
    {
      "component": "Grid",
      "relationship": "Place cards in a responsive Grid",
      "example": "<Grid mdCols={3} gap=\"lg\"><ArticleCard ... /></Grid>"
    }
  ],
  "relatedComponents": [
    "Card",
    "Grid",
    "FeaturedPost",
    "ResourceHub"
  ]
}
